mapper.sql:
WHERE member_id = #{memberId}

    AND (CASE WHEN status = 'PENDING_MEMBER_CONFIRMATION' AND expires_at <= #{now}
              THEN 'EXPIRED' ELSE status END) = #{status}

mapper.select:
SELECT record_id, member_id, fingerprint, fingerprint_member_id, document, NULL AS photo, media_type, status, created_at, expires_at
FROM dietary_record 
ORDER BY created_at DESC, record_id ASC LIMIT #{size} OFFSET #{offset}
